#!/bin/zsh
set -euo pipefail
cd "${0:A:h:h}"
# Requires the actual companion service and private token generated by start_service.sh.
[[ -f var/service/pairing-token ]] || { print -u2 'Start scripts/start_service.sh first.'; exit 1; }
curl --fail --silent http://127.0.0.1:8767/v1/health > /dev/null
sim_id=$(xcrun simctl list devices available -j | .venv/bin/python -c 'import sys,json; d=json.load(sys.stdin); print(next((x["udid"] for a in d["devices"].values() for x in a if x["name"]=="ReverseCAD Trial"), ""))')
if [[ -z "$sim_id" ]]; then
  sim_id=$(xcrun simctl create 'ReverseCAD Trial' com.apple.CoreSimulator.SimDeviceType.iPhone-17-Pro com.apple.CoreSimulator.SimRuntime.iOS-26-5)
fi
xcrun simctl boot "$sim_id" 2>/dev/null || true
xcrun simctl bootstatus "$sim_id" -b
xcodegen generate --spec ios/project.yml
run_id=$(date +%Y%m%d-%H%M%S)
mkdir -p reports
xcodebuild -project ios/ReverseCAD.xcodeproj -scheme ReverseCAD -configuration Debug -destination "id=$sim_id" -derivedDataPath var/DerivedData -resultBundlePath "reports/ios-tests-$run_id.xcresult" -parallel-testing-enabled NO CODE_SIGNING_ALLOWED=NO test > "reports/ios-tests-$run_id.log" 2>&1
print "XCTest results: reports/ios-tests-$run_id.xcresult"
